script:
applyWorkEffortsStyles();

// Клиентский скрипт для Doctype "Project"
frappe.ui.form.on("Project", {
    refresh: function(frm) {
        render_work_efforts_table(frm);
    }
});

frappe.ui.form.on("Project", {
    onload: function(frm) {
        frm.show_assignments = false;
        render_work_efforts_table(frm);
    }
});

/**
 * Отрисовка таблицы «Трудозатраты»
 */
function render_work_efforts_table(frm) {
    // Инициализируем show_assignments, если не задано
    if (frm.show_assignments === undefined) {
        frm.show_assignments = false;
    }
    
    if ( frm.last_loaded_project == frm.doc.name && ( new Date() - frm.last_loaded_time ) < 300000 ) {
        console.log("Загружены данные проекта и прошло менее 5 минут..");
        return;
    }

    let wrapper = frm.get_field("custom_work_efforts").$wrapper;
    wrapper.addClass("work_efforts_container");

    wrapper.empty();
    frm.aggregatedTasks = null;
    frm.we_periods = {};

    let controls = $('<div class="work-efforts-controls"></div>').appendTo(wrapper);
    let table_container = $('<div class="work-efforts-table"></div>').appendTo(wrapper);
    let legend_container = $('<div class="work-efforts-legend"></div>').appendTo(wrapper);

    // Добавляем все элементы последовательно
    controls.append(`
        <button class="btn btn-default" id="we_save_plan">${__('Сохранить план')}</button>
        <button class="btn btn-default" id="toggle_plan">${__("Показать план")}</button>
        <button class="btn btn-default" id="toggle_delta">${__("Показать Δ")}</button>
    `);
    
    addViewOptionsControl(frm, controls);
    
    // Определяем переменные
    let selectedPeriodType = "month";
    let selectedUnit = "hours";
    let all_roles = get_project_roles(frm);
    
    // Добавляем чекбокс "Назначения"
    let checkbox_wrapper = $('<div class="assignments-checkbox-wrapper"></div>').appendTo(controls);
    
    let assignments_checkbox = frappe.ui.form.make_control({
        parent: checkbox_wrapper,
        df: {
            fieldtype: 'Check',
            fieldname: 'show_assignments',
            label: __("Назначения"),
            onchange: function() {
                frm.show_assignments = this.get_value();
                
                let newStickyCount = frm.show_assignments ? 5 : 4;
                frm.work_efforts_dt.setStickyColumnsCount(newStickyCount);
                
                // Используем updateTable вместо refresh для сохранения иерархии
                if (frm.show_assignments && !allAssignmentsLoaded) {
                    load_all_assignments_if_needed(frm).then(() => {
                        updateTable(frm, selectedPeriodType, selectedUnit);
                    });
                } else {
                    updateTable(frm, selectedPeriodType, selectedUnit);
                }
            }
        },
        value: frm.show_assignments,
        only_input: false,
        render_input: true
    });
    assignments_checkbox.refresh();

    // Добавляем кнопку "Проверить" с margin-left: auto
    controls.append(`
        <div class="btn-group">
            <button class="btn btn-default dropdown-toggle" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">
                ${__('Проверить')} <span class="caret"></span>
            </button>
            <ul class="dropdown-menu dropdown-menu-right">
                <li id="check_plan_load">${__('Наличие плановых трудозатрат')}</li>
                <li id="check_workload_overload">${__('Загрузка превышает прогноз трудозатрат')}</li>
            </ul>
        </div>
    `);
    
    frm.hide_plan = frm.hide_plan || true;
    frm.hide_delta = frm.hide_delta || true;

    controls.find('#we_save_plan').on('click', function() {
        if ( !frm.work_efforts_dt.rowmanager.getCheckedRows()?.length ) {
            frappe.msgprint(__("Выберите задачи, для которых необходимо сохранить плановые данные."));
        } else {
            frappe.confirm(
                __("Вы уверены, что хотите сохранить выбранные прогнозные / фактические данные как плановые?"),
                () => {
                    save_forecast_as_plan(frm);
                },
                () => {
                    frappe.show_alert(__("Операция отменена"), 3);
                }
            );
        }
    });
    
    controls.find('#toggle_plan').on('click', function() {
        frm.hide_plan = !frm.hide_plan;
        $(this).text(frm.hide_plan ? __("Показать план") : __("Скрыть план"));
        updateTable(frm, selectedPeriodType, selectedUnit);
        render_work_efforts_chart(frm);
    });
    
    controls.find('#toggle_delta').on('click', function() {
        frm.hide_delta = !frm.hide_delta;
        $(this).text(frm.hide_delta ? __("Показать Δ") : __("Скрыть Δ"));
        updateTable(frm, selectedPeriodType, selectedUnit);
    });
    
    controls.find('#check_plan_load').on('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        check_plan_load_for_percentage_assignments(frm);
    });
    
    //ISS-2025-02858 + ст.186
    controls.find('#check_workload_overload').on('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        perform_overload_check(frm);
    });
    //

    // Инициализация таблицы
    function init_table() {
        let columns = get_columns_definition(frm, selectedPeriodType, selectedUnit);
        let stickyCount = frm.show_assignments ? 5 : 4;
        
        frm.work_efforts_dt = new StickyDataTable(table_container[0], {
            stickyColumnsCount: stickyCount,
            columns: columns,
            data: [],
            inlineFilters: false,
            layout: "fixed",
            logs: true,
            disableReorderColumn: true,
            serialNoColumn: true,
            checkboxColumn: true,
            checkedRowStatus: true,
            dynamicRowHeight: true,
            getDynamicRowHeight: function(instance, index) {
                let data = instance.datamanager.getData(index);
                if (!data || !data.role_data) return 28;
                
                // Базовая высота: отступы + высота каждой роли (24px)
                let h = 4 + 24 * ( data.role_data.length + ((all_roles.length - 1) > data.role_data.length) );
            
                return h;
            },
            //END
            showTotalRow: true,
            cellHeight: null,
            treeView: true,
            freezeMessage: __("Идет загрузка данных.."),
            hooks: {
                columnTotal(columnValues, cell) {
                    if (cell.column.id == "total") {
                        let periods = get_display_periods( frm, frm.currentPeriodType || "month");
                        let all_roles = get_project_roles(frm).filter(r => r );
                
                        let total_plan = 0;
                        let total_actual = 0;
    
                        periods.forEach(function(period) {
                            let r = calc_we_column_total( frm, all_roles, period, !frm.hide_plan );
                            total_plan += r.plan;
                            total_actual += r.actual;
                        });
                        
                        let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                        
                        return `<div class="work-efforts-group">
                            ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                            <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>
                            ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat(delta).toFixed(1)}%</span></div>`}
                          </div>`;
                          
                    } else if ( cell.colIndex == 0 ) {
                        return __('Итого');
                    } else if ( cell.colIndex > 1 ) {
                        let parts = cell.column.id.split("_");
                        
                        if(parts.length == 3) {
                            let year = parts[1];
                            let month = parts[2];
                            let periods = get_display_periods( frm, frm.currentPeriodType || "month");
                            let period = periods.find(p => p.year == year && p.month == month);
                        
                            let all_roles = get_project_roles(frm).filter(r => r );
                            
                            let r = calc_we_column_total( frm, all_roles, period, !frm.hide_plan );
                            let total_plan = r.plan;
                            let total_actual = r.actual;
                        
                            let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                            
                            return `<div class="work-efforts-group"
                                data-year="${year}" 
                                data-month="${month}">
                                ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                                <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>
                                ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat( delta ).toFixed(1)}%</span></div>`}
                              </div>`;
                        }
                    }
                    return "";
                }
            }
        });

        load_work_efforts_data(frm, selectedPeriodType, selectedUnit);
    }
    init_table();
    frm.last_loaded_project = frm.doc.name;
    frm.last_loaded_time = new Date();
    
    // Рендерим легенду
    render_legend(legend_container);
}

/**
 * Отрисовка легенды под таблицей (стилистика из референса, цвета наши)
 */
function render_legend(container) {
    let legend_html = `
        <div style="display: flex; flex-wrap: wrap; align-items: center; gap: 16px 24px; padding: 8px 12px; background: var(--fg-color); border: 1px solid var(--border-color); border-radius: 4px;">
            
            <!-- Плановые сроки -->
            <div style="display: flex; align-items: center; gap: 6px;">
                <div style="width: 16px; height: 16px; background-color: #ede0f5; border-radius: 2px; border: 1px solid var(--border-color);"></div>
                <span>${__("Плановые сроки задачи")}</span>
            </div>
            
            <!-- Прогнозные сроки -->
            <div style="display: flex; align-items: center; gap: 6px;">
                <div style="width: 16px; height: 16px; background-color: #e0e8ff; border-radius: 2px; border: 1px solid var(--border-color);"></div>
                <span>${__("Прогнозные сроки задачи")}</span>
            </div>
            
            <!-- Загрузка -->
            <div style="display: flex; align-items: center; gap: 6px;">
                <div style="width: 16px; height: 16px; background-color: #e0e8ff; border-radius: 2px; border: 1px solid var(--border-color); position: relative;">
                    <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-image: radial-gradient(circle, #c8d0d8 1px, transparent 1px); background-size: 4px 4px; border-radius: 1px;"></div>
                </div>
                <span>${__("Загрузка")}</span>
            </div>
            
            <!-- Отсутствие плана -->
            <div style="display: flex; align-items: center; gap: 6px;">
                <div style="width: 16px; height: 16px; display: flex; align-items: center; justify-content: center; background: var(--fg-color); border: 1px solid var(--border-color); border-radius: 2px;">
                    <span style="color: var(--alert-text-warning); font-weight: 700; font-size: 11px;">0</span>
                </div>
                <span>${__("Отсутствует план при наличии загрузки")}</span>
            </div>
        </div>
    `;
    
    container.html(legend_html);
}

// Добавьте эти функции в ваш клиентский скрипт

let _sum_we_cache = {};
let _columnTotalCache = {};

function calc_we_column_total_optimized(frm, roles, period, calc_plan = true, calc_fact = false) {
    const cacheKey = `total_${period.year}_${period.month}_${calc_plan}_${calc_fact}`;
    
    // Проверяем кэш
    if (_columnTotalCache[cacheKey] !== undefined) {
        return _columnTotalCache[cacheKey];
    }
    
    let plan = 0;
    let actual = 0;
    
    // Если нет данных, возвращаем нули
    if (!frm.aggregatedTasks) {
        return { plan: 0, actual: 0 };
    }
    
    const tasks = Object.values(frm.aggregatedTasks);
    
    // Фильтруем роли (убираем пустые)
    const filteredRoles = roles.filter(r => r && r.trim());
    
    // Создаем индекс задач по parent_task для быстрого поиска
    if (!frm._tasksByParent) {
        frm._tasksByParent = {};
        tasks.forEach(task => {
            const parent = task.parent_task || '';
            if (!frm._tasksByParent[parent]) {
                frm._tasksByParent[parent] = [];
            }
            frm._tasksByParent[parent].push(task);
        });
    }
    
    // Функция для быстрого получения суммы по дочерним задачам
    const getChildSum = (() => {
        const childSumCache = {};
        
        return function(taskId, role, periodKey, valueType = "forecast") {
            const cacheKey = `child_${taskId}_${role}_${periodKey}_${valueType}`;
            
            if (childSumCache[cacheKey] !== undefined) {
                return childSumCache[cacheKey];
            }
            
            let sum = 0;
            const children = frm._tasksByParent[taskId] || [];
            
            for (let i = 0; i < children.length; i++) {
                const child = children[i];
                const roleEntry = child.role_data?.find(r => r.role === role);
                
                if (roleEntry) {
                    const key = `${valueType}_${periodKey}`;
                    const value = parseFloat(roleEntry[key]) || 0;
                    
                    if (value > 0) {
                        sum += value;
                    } else {
                        // Рекурсивно ищем в потомках
                        sum += getChildSum(child.value, role, periodKey, valueType);
                    }
                }
            }
            
            childSumCache[cacheKey] = sum;
            return sum;
        };
    })();
    
    const periodKey = `${period.year}_${period.month}`;
    const valueKey = (period.is_past || calc_fact) ? "fact" : "forecast";
    
    // Для каждой роли считаем сумму
    for (const role of filteredRoles) {
        let rolePlan = 0;
        let roleActual = 0;
        
        // Находим корневые задачи для этой роли
        const rootTasks = tasks.filter(t => !t.parent_task);
        
        for (const root of rootTasks) {
            const roleEntry = root.role_data?.find(r => r.role === role);
            
            // Плановые данные
            if (calc_plan) {
                let planSum = roleEntry ? parseFloat(roleEntry[`plan_${periodKey}`]) || 0 : 0;
                if (!planSum) {
                    planSum = getChildSum(root.value, role, periodKey, "plan");
                }
                rolePlan += planSum;
            }
            
            // Фактические/прогнозные данные
            let actualSum = roleEntry ? parseFloat(roleEntry[`${valueKey}_${periodKey}`]) || 0 : 0;
            if (!actualSum) {
                actualSum = getChildSum(root.value, role, periodKey, valueKey);
            }
            roleActual += actualSum;
        }
        
        plan += rolePlan;
        actual += roleActual;
    }
    
    const result = { plan, actual };
    _columnTotalCache[cacheKey] = result;
    
    return result;
}

function calc_we_column_total(frm, roles, period, calc_plan = true, calc_fact = false) {
    return calc_we_column_total_optimized(frm, roles, period, calc_plan, calc_fact);
}

function clearTaskIndexCacheFor(tasks) {
    _sum_we_cache = {};
    _columnTotalCache = {};
    if (cur_frm) {
        cur_frm._tasksByParent = null;
    }
}

function addViewOptionsControl(frm, controls) {
    frm.view_options = frm.view_options || __("Прогноз и факт");
    const control = frappe.ui.form.make_control({
		parent: controls,
		df: {
			fieldtype: 'Select',
			fieldname: "view-options",
			options: [
                __("Прогноз и факт"),
                __("Только прогноз"),
                __("Только факт"),
            ],
			get_status: function(i) {
                return "Write";
            },
            change: async function(i){
                if ( this.value != this.last_value ) {
                    frm.we_periods = {};
                    frm.view_options = this.value;
                    updateTable( frm, "month", "hours" );
                    render_work_efforts_chart(frm);
                }
            }
		},
		value: frm.view_options,
		only_input: true,
        render_input: true
	});
}

function get_project_roles(frm) {
    let roles = [];
    if (frm.doc.custom_ts_details) {
        roles = frm.doc.custom_ts_details.map((x) => x.pt_role );
    }
    roles.push("");
    return Array.from( new Set(roles));
}

function get_display_periods(frm, periodType) {
    if ( frm.we_periods && frm.we_periods[ periodType ] ) return frm.we_periods[ periodType ];
    if ( !frm.we_periods ) frm.we_periods = {};
    frm.view_options = frm.view_options || __("Прогноз и факт");
    let periods = [];
    let month_start = frappe.datetime.month_start();
    let start_date = frm.doc.expected_start_date ? frm.doc.expected_start_date : month_start;
    let start = frappe.datetime.str_to_obj(start_date);
    let end_date = frm.doc.expected_end_date ? frm.doc.expected_end_date : frappe.datetime.add_months(start, 12);
    let end = frappe.datetime.str_to_obj(end_date);

    if (periodType === "month") {
        let current = start;
        while (frappe.datetime.obj_to_str(current) <= frappe.datetime.obj_to_str(end)) {
            let year = current.getFullYear();
            let i = current.getMonth();
            let is_past = ( frm.view_options == __("Прогноз и факт") ) 
                ? frappe.datetime.obj_to_str(current) < month_start
                : ( frm.view_options == __("Только факт") );
            periods.push({ year: year, month: i + 1, is_past: is_past });
            current = frappe.datetime.str_to_obj( frappe.datetime.add_months(current, 1) );
        }
    }
    frm.we_periods[ periodType ] = periods;
    return periods;
}

function updateTable(frm, periodType, unit, skipRestore = false) {
    console.log ('UPDATE TABLE');
    frm.work_efforts_dt.freeze();
    let visibleRows = frm.work_efforts_dt.bodyRenderer.visibleRowIndices;
    
    return new Promise((resolve) => {
        frm.work_efforts_dt.refresh(
            Object.values(frm.aggregatedTasks),
            get_columns_definition(frm, periodType, unit)
        );
        
        frm.work_efforts_dt.rowmanager.showRows(visibleRows);
        cur_frm.work_efforts_dt.bodyScrollable.dispatchEvent(new CustomEvent('scroll'));
        frm.work_efforts_dt.unfreeze();
        
        // При внесении прогноза и плана исчезали загрузка и назначения
        // Добавил восстановление карты загрузки и перезагрузку назначений после обновления таблицы
        if (!skipRestore) {
            setTimeout(() => {
                // Восстанавливаем карту загрузки
                buildWorkloadPeriodsMap(frm).then(() => {
                    // Если чекбокс включен - восстанавливаем назначения
                    if (frm.show_assignments) {
                        load_all_assignments_if_needed(frm).then(() => {
                            // Обновляем ТОЛЬКО колонку назначений (не пересоздавая таблицу)
                            frm.work_efforts_dt.refresh(
                                Object.values(frm.aggregatedTasks),
                                get_columns_definition(frm, periodType, unit)
                            );
                            
                            // Фикс от 24.04.2026 --- ПОСЛЕ ОБНОВЛЕНИЯ АВАТАРОВ - СВОРАЧИВАЕМ ВСЕ УЗЛЫ
                            if (frm.work_efforts_dt && frm.work_efforts_dt.rowmanager && frm.work_efforts_dt.rowmanager.collapseAllNodes) {
                                frm.work_efforts_dt.rowmanager.collapseAllNodes();
                            }
                            
                        });
                    }
                });
            }, 100);
        }
        
        setTimeout(resolve, 300);
    });
}
/**
 * Загрузка данных для таблицы «Трудозатраты»
 *
 * Здесь необходимо объединить данные:
 * – иерархии задач (с использованием whitelisted‑метода custom_task_get_children),
 * – данных из DocType "Project Work Efforts" (плановые и прогнозные данные),
 * – фактических данных из "User Timesheet Position".
 */
/**
 * Загрузка данных для таблицы «Трудозатраты» - оптимизированная версия
 */
function load_work_efforts_data(frm, periodType, unit, updateRows) {
    // ОЧИСТКА КЭША ПРИ ЗАГРУЗКЕ НОВЫХ ДАННЫХ
    clear_assignments_cache();
    
    // Проверяем кэш (5 минут)
    if (frm.last_loaded_project == frm.doc.name && (new Date() - frm.last_loaded_time) < 300000) {
        console.log("Используем кэшированные данные проекта (прошло менее 5 минут)");
        return;
    }
    
    frm.work_efforts_dt.freeze();
    console.time("load_work_efforts_data_optimized");
    
    clearTaskIndexCacheFor(frm.aggregatedTasks);
    
    // Единый запрос на сервер для получения всех данных
    frappe.call({
        method: "get_work_efforts_consolidated_data",
        args: {
            project: frm.doc.name,
            view_options: frm.view_options || "Прогноз и факт"
        },
        freeze_message: __("Загрузка данных о трудозатратах..."),
        callback: function(r) {
            if (r.message) {
                console.timeLog("load_work_efforts_data_optimized", "Данные получены");
                
                let tasksArray = r.message;
                frm.aggregatedTasks = {};
                
                tasksArray.forEach(task => {
                    if (task && task.value) {
                        frm.aggregatedTasks[task.value] = task;
                    }
                });
                
                console.log("Загруженные задачи:", Object.keys(frm.aggregatedTasks));
                
                _sum_we_cache = {};
                
                let table_data = tasksArray;
                let visibleRows;
                
                if (updateRows) {
                    visibleRows = frm.work_efforts_dt.bodyRenderer.visibleRowIndices;
                }
                
                // Сначала строим карту загрузки, потом отрисовываем таблицу
                buildWorkloadPeriodsMap(frm).then(() => {
                    console.time("work_efforts_dt.refresh");
                    frm.work_efforts_dt.refresh(table_data);
                    frm.work_efforts_dt.rowmanager.collapseAllNodes();
                    console.timeEnd("work_efforts_dt.refresh");
                    
                    if (visibleRows) {
                        frm.work_efforts_dt.rowmanager.showRows(visibleRows);
                    }
                    
                    frm.work_efforts_dt.unfreeze();
                    
                    // Дополнительные действия после загрузки
                    setCellStyles();
                    if (typeof render_labour_percentage_chart === 'function') {
                        render_labour_percentage_chart(frm);
                    }
                    if (typeof render_work_efforts_chart === 'function') {
                        render_work_efforts_chart(frm);
                    }
                    if (typeof updateTaskDimension === 'function') {
                        updateTaskDimension(frm);
                    }
                    
                    console.timeEnd("load_work_efforts_data_optimized");
                
                    frm.last_loaded_project = frm.doc.name;
                    frm.last_loaded_time = new Date();
                });
            }
        },
        error: function(err) {
            console.error("Ошибка при загрузке данных:", err);
            frappe.msgprint(__("Ошибка при загрузке данных о трудозатратах"));
            frm.work_efforts_dt.unfreeze();
        }
    });
}

//Функция для "свертывания" (rollup) фактических данных:
//для каждой задачи суммируются фактические трудозатраты (fact_*) из всех дочерних задач с той же ролью.
function rollup_fact_data(aggregatedTasks) {
    // Получаем массив задач, отсортированный по убыванию indent (то есть от самых глубоких к родительским)
    let tasksArray = Object.values(aggregatedTasks).sort((a, b) => b.indent - a.indent);
    tasksArray.forEach(child => {
        if (child.parent_task && aggregatedTasks[child.parent_task]) {
            let parent = aggregatedTasks[child.parent_task];
            // Для каждой записи по роли в дочерней задаче
            child.role_data.forEach(childRoleEntry => {
                let role = childRoleEntry.role;
                // Ищем в родительской задаче запись для той же роли
                let parentRoleEntry = parent.role_data.find(r => r.role === role);
                // Перебираем все свойства, начинающиеся с "fact_"
                for (let prop in childRoleEntry) {
                    if (prop.startsWith("fact_")) {
                        if (!parentRoleEntry) {
                            parentRoleEntry = { role: role };
                            parent.role_data.push(parentRoleEntry);
                        }
                        if (prop.startsWith("fact_utps")) {
                            if ( !parentRoleEntry[prop] ) {
                                parentRoleEntry[prop] = [];
                            }
                            parentRoleEntry[prop].push(...(childRoleEntry[prop] || [] ));
                        } else {
                            let childFact = parseFloat(childRoleEntry[prop]) || 0;
                            if (childFact) {
                                parentRoleEntry[prop] = (parseFloat(parentRoleEntry[prop]) || 0) + childFact;
                            }
                        }
                    }
                }
            });
        }
    });
}

