function open_tasks_for_note(frm) {
  if (!frm.doc.name) return;

  // Сначала пробуем фильтровать по полю Task.meeting_notes (если оно есть)
  frappe.model.with_doctype('Task', () => {
    const hasLinkField = !!frappe.meta.get_docfield('Task', 'meeting_notes');
    if (hasLinkField) {
      frappe.route_options = { meeting_notes: frm.doc.name };
      frappe.set_route('List', 'Task');
      return;
    }

    // Если поля нет — используем ссылки на задачи из таблицы Assignments
    const ids = (frm.doc.assignments || []).map(r => r.task).filter(Boolean);
    if (ids.length) {
      frappe.route_options = { name: ['in', ids] };
      frappe.set_route('List', 'Task');
    } else {
      frappe.msgprint(__('В этом протоколе пока нет созданных задач.'));
    }
  });
}

