function init_estimations_lock(frm) {
    //console.log('[DEBUG] init_estimations_lock called');
    if (!frm.fields_dict.estimations) return;

    const lock_rows = () => {
        if (!frm.doc.estimations) return;

        frm.doc.estimations.forEach((row) => {
            const $row = $(`[data-name="${row.name}"]`);
            if (!$row.length) return;

            // --- Блокировка чекбокса удаления для оценок > 0 ---
            if (parseFloat(row.grade) > 0) {
                $row.find('.grid-row-check')
                    .prop('disabled', true)
                    .css('opacity', '0.6')
                    .css('cursor', 'not-allowed');
            } else {
                // Разблокируем если оценка = 0
                $row.find('.grid-row-check')
                    .prop('disabled', false)
                    .css('opacity', '1')
                    .css('cursor', 'pointer');
            }
        });
    };

    // Первоначальная блокировка с задержкой
    setTimeout(lock_rows, 300);
}

