const ICONS = {
  "Согласовано": "✅",
  "Не согласовано": "❌",
};

async function processUTWorkflow(frm) {
    const isOwner = frappe.session.user == frm.doc.timesheet_from;

    if (!isOwner && frm.doc.ut_status == 'На согласовании' && cur_frm.ts_positions.length) {

        // Получаем список ID всех позиций табеля
        const positionNames = frm.ts_positions.map(pos => pos.name);

        // Проверяем наличие активных Workflow Task для этих позиций
        const userTasks = await frappe.db.get_list('Workflow Task', {
            fields: ['name', 'wt_docname'],
            filters: {
                doc: "User Timesheet Position",
                wt_docname: ["in", positionNames],
                status: 'Working',
                "_assign": ["like", "%" + frappe.session.user + "%"] 
            }
        });

        // Если нет активных задач workflow для текущего пользователя - не показываем кнопки
        if (userTasks.length === 0) {
            console.log("No active workflow tasks found for current user");
            return;
        }

        // Создаем маппинг task -> position для быстрого поиска
        const taskPositionMap = {};
        userTasks.forEach(task => {
            taskPositionMap[task.wt_docname] = task;
        });

        // Фильтруем позиции, оставляем только те, для которых есть активные задачи
        const positionsWithActiveTasks = frm.ts_positions.filter(pos => 
            taskPositionMap[pos.name]
        );

        // Если после фильтрации не осталось позиций - не показываем кнопки
        if (positionsWithActiveTasks.length === 0) {
            console.log("No positions with active workflow tasks for current user");
            return;
        }

        // Обновляем ссылку на позиции (используем только те, у которых есть активные задачи)
        frm.ts_positions_with_active_tasks = positionsWithActiveTasks;

        frappe.xcall('frappe.model.workflow.get_common_transition_actions', {  
            docs: positionsWithActiveTasks,  
            doctype: 'User Timesheet Position'  
        }).then(async (actions) => {  
            // actions - массив общих действий  
            for (action of actions) {
                let icon = ICONS[action];
                let btn = frm.add_custom_button((icon ? icon + " " : "") + __(action), async function() {
                    let e = event;
                    let action = decodeURI($(event.target).data("action"));
                    let position = positionsWithActiveTasks[0];
                    position.doctype = "User Timesheet Position";

                    frappe.workflow.get_transitions(position).then(async (transitions) => {  
                        let cur_transition = transitions.find((t) => t.action == action);

                        if (cur_transition?.custom_comment_is_required) {
                            console.log("Need WF action comments..");
                            frappe.prompt({
                                fieldtype: 'Data',
                                label: 'Введите комментарий',
                                fieldname: 'comment',
                                reqd: 1
                            }, async (data) => {
                                if (!data.comment) {
                                    reject("Комментарий не может быть пустым");
                                    return;
                                }
                                await updateUTPositions(frm, positionsWithActiveTasks, cur_transition.next_state, data.comment);
                            }, `Комментарий для действия "${cur_transition.action}"`, __('Сохранить'));

                        } else {
                            await updateUTPositions(frm, positionsWithActiveTasks, cur_transition.next_state);
                        }
                    });
                });
                $(btn).data("action", action);
            }
        });
    }
}

async function updateUTPositions(frm, updatedPositions, pos_status, comment=null) {
    frappe.call({
        method: "set_timesheet_status",
        args: {
            positions: updatedPositions,
            pos_status: pos_status,
        },
        silent: true,
        freeze: true,
        freeze_message: __("Сохранение данных..")
    }).then(async r => {
        if ( comment ) {
            for (item of updatedPositions) {
                await addUTComment( item.name, comment );
            }
        }
    }).then(r => {
        frappe.show_alert({
            message:__('Данные сохранены'),
            indicator:'green'
        }, 5);
        frm.reload_doc();
    }).catch(err => { 
        let message;
        if ( err && err.responseJSON ) {
            message = err.responseJSON.exception;
        } else {
            message = String( err );
        }
        frappe.throw(__("Ошибка при сохранении данных: ") + message );
    });
}

