                            //     if (updates.write !== undefined) rights.push(updates.write === 1 ? "запись" : "без записи");
                            //     if (updates.share !== undefined) rights.push(updates.share === 1 ? "расшаривание" : "без расшаривания");
                            //     
                            //     frappe.show_alert({
                            //         message: __("Обновлены права ({0}) для {1}", [rights.join(", "), participant.user]),
                            //         indicator: 'blue'
                            //     }, 3);
                            // }
                        }
                    });
                }
            }
        });
    }
}

