function set_parent_task_query(frm) {
    // Проверяем значение поля type
    if (frm.doc.type === "Stage") {
        // Устанавливаем фильтр для поля parent_task для типа Stage
        frm.set_query("parent_task", function() {
            return {
                filters: [
                    ["Task", "type", "in", ["Phase", "Sprint"]]
                ]
            };
        });
    } else if (frm.doc.type === "Sprint") {
        // Устанавливаем фильтр для поля parent_task для типа Sprint
        frm.set_query("parent_task", function() {
            return {
                filters: [
                    ["Task", "type", "in", ["Phase", "Stage"]]
                ]
            };
        });
        
    } else {
        // Если type не "Stage", "Sprint" или "Phase", фильтр не устанавливается
        frm.set_query("parent_task", null); // Сбрасываем фильтр
    }

    // Скрываем поле confirm и ограничиваем значения в поле status
    if (["Stage", "Sprint", "Phase"].includes(frm.doc.type)) {
        frm.set_df_property('confirm', 'hidden', 1); // Скрываем поле confirm
        frm.set_df_property('status', 'options', 'Open\nWorking\nOverdue\nTemplate\nCompleted\nCancelled'); // Ограничиваем значения в поле status
    } else {
        frm.set_df_property('confirm', 'hidden', 0); // Показываем поле confirm
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review\nOverdue\nTemplate\nCompleted\nCancelled'); 
    }
}

