async function calculate_levels(frm) {
    const promises = frm.doc.custom_ts_details
        .filter(row => row.pt_participant)
        .map(row => calculate_row_level(frm, row));
    
    await Promise.all(promises);
    frm.refresh_field('custom_ts_details');
}

async function calculate_row_level(frm, row) {
    if (!row.pt_participant) return;
    
    try {
        const worker = await frappe.db.get_value('Worker', 
            { wuser: row.pt_participant }, 
            ['name']
        );
        
        if (!worker?.message?.name) return;
        
        const workerDoc = await frappe.db.get_doc('Worker', worker.message.name);
        
        if (!workerDoc?.worker_level || workerDoc.worker_level.length === 0) return;
        
        const now = new Date();
        const validLevels = workerDoc.worker_level
            .filter(level => level.wl_valid_from && new Date(level.wl_valid_from) <= now)
            .sort((a, b) => new Date(b.wl_valid_from) - new Date(a.wl_valid_from));
        
        if (validLevels.length === 0) return;
        
        row.base_cost_level = validLevels[0].wl_cosl_level;
        
    } catch (err) {
        // Ошибки обрабатываются silently
        console.error(err);
    }
}

