function getPayload( frm ) {
    let deleted = frm.deletedPositions;

    return {
        timesheet_name: frm.doc.name,
        positions: ( deleted 
            ? frm.ts_positions.filter(( pos ) => !deleted.some( ( del ) => del == pos.name ) )
            : frm.ts_positions )
    };
}

async function checkLimits(frm) {
    const warnings = [];

    if (!frm.ts_positions || !frm.doc.name) return warnings;

    const payload = getPayload( frm );

    let result = await frappe.call({
        method: 'calculate_timesheet_limits',
        args: payload,
    });

    if (result?.message) {
        result.message.forEach(r => {
           if (r.status == "block" || r.status == "warning") {
                warnings.push(r);
            } 
        });
    }

    return warnings;
}

