// Функция для проверки плановых трудозатрат согласно настройки проекта ISS-2025-01298
function checkPlannedHoursAndLimits(frm) {
    return new Promise(async (resolve) => {
        const errors = [];
        const warnings = [];

        try {
            const positions = frm.ts_positions || [];

            if (!positions.length || !frm.doc.name) {
                return resolve({ errors, warnings });
            }

            // Упрощенный вызов - передаем только необходимые данные
            const planCheck = await frappe.call({
                method: 'calculate_timesheet_limits',
                args: {
                    timesheet_name: frm.doc.name,
                    positions: positions.map(p => ({
                        name: p.name,
                        document_name: p.document_name,
                        project_role: p.project_role,
                        project: p.project,
                        status: p.status,
                        all_hours: p.all_hours
                        // Убрали передачу plan_required - теперь определяется на сервере
                    }))
                }
            });

            // Обработка результатов остается прежней
            (planCheck.message || []).forEach(r => {
                if (r.status === "block") {
                    if (r.planned_hours > 0) {
                        const max_hrs = r.limit * r.planned_hours / 100;
                        errors.push(
                            `Трудозатраты по задаче "${r.task_subject}" (роль: ${r.role}) ` +
                            `превысили блокирующий лимит (${max_hrs} ч.) ` +
                            `на ${r.total_hours - max_hrs} часа(ов).`
                        );
                    } else {
                        errors.push(
                            `Для задачи "${r.task_subject}" (роль: ${r.role}) ` +
                            `не определены обязательные плановые трудозатраты`
                        );
                    }
                } else if (r.status === "warning") {
                    warnings.push(r);
                }
            });
        } catch (error) {
            console.error('Error in checkPlannedHoursAndLimits:', error);
            errors.push('Ошибка при проверке плановых трудозатрат и лимитов');
        }

        resolve({ errors, warnings });
    });
}

