// Функция для полной имитации пользовательского ввода (без изменений)
function simulateUserInput(element, value) {
    element.focus();
    element.value = value;
    
    const events = ['input', 'change', 'keydown', 'keypress', 'keyup'];
    events.forEach(eventType => {
        const event = new Event(eventType, {
            bubbles: true,
            cancelable: true
        });
        element.dispatchEvent(event);
    });
    
    setTimeout(() => {
        const blurEvent = new Event('blur', { bubbles: true });
        element.dispatchEvent(blurEvent);
    }, 100);
}

function getPositionSignature(position) {
    return [
        position?.document_type || '',
        position?.document_name || '',
        position?.user || '',
        position?.project || '',
        position?.project_role || ''
    ].join('::');
}

function getExistingPositionSignatures(frm) {
    const signatures = new Set();
    const positions = Array.isArray(frm?.ts_positions) ? frm.ts_positions : [];
    const deletedPositions = Array.isArray(frm?.deletedPositions) ? frm.deletedPositions : [];
    const visibleRowIds = new Set();

    $('.table-row').each(function() {
        visibleRowIds.add(String($(this).attr('id')));
    });

    for (const position of positions) {
        const positionId = String(position?.name || '');

        // Игнорируем удаленные из интерфейса строки, чтобы их можно было добавить повторно до сохранения.
        if (deletedPositions.includes(position?.name) || (visibleRowIds.size > 0 && positionId && !visibleRowIds.has(positionId))) {
            continue;
        }

        signatures.add(getPositionSignature(position));
    }

    return signatures;
}

function filterPositionsAlreadyAdded(frm, positions) {
    const existingSignatures = getExistingPositionSignatures(frm);
    const filteredPositions = [];
    let duplicatesCount = 0;

    for (const position of positions) {
        const signature = getPositionSignature(position);

        if (existingSignatures.has(signature)) {
            duplicatesCount++;
            continue;
        }

        existingSignatures.add(signature);
        filteredPositions.push(position);
    }

    return {
        positions: filteredPositions,
        duplicatesCount: duplicatesCount
    };
}

// Выносим обработку ответа в отдельную функцию
function handle_copy_positions_response(result) {
    let message = '';
    let indicator = 'orange';

    // Формируем информативное сообщение
    if (result.copied_count > 0) {
        message = __('Успешно скопировано: {0}', [result.copied_count]);
        indicator = 'green';
        
        if (result.duplicates_count > 0 /*|| result.invalid_count > 0/**/) {
            message += '<br/>'; // Перенос строки
        }
    }
    
    if (result.duplicates_count > 0) {
        message += __('Пропущено дубликатов: {0}', [result.duplicates_count]);
        if (result.invalid_count > 0) {
            message += '<br/>'; // Перенос строки
        }
    }
    
    /*if (result.invalid_count > 0) {
        message += __('Пропущено невалидных: {0}', [result.invalid_count]);
    }/**/

    if (!message && result.message) {
        message = result.message;
    }
    
    // Показываем уведомление
    frappe.show_alert({
        message: message,
        indicator: indicator
    }, 8);
}

