// ISS-2025-02430: выносим общий вызов серверных методов копирования в один обработчик
function handleCopyRequest(frm, methodName, customers, fullDates, filteredHolidays, validTasks) {
    disableCopyPosition(frm);
    frappe.call({
        method: methodName,
        args: {
            doc: frm.doc,
            valid_tasks: validTasks || []
        },
        freeze: true,
        silent: true,
        callback: function(r) {
            console.log('Full server response:', r); // Для отладки
            const responseMessage = r?.message?.message || __('Ошибка при обработке запроса');
            const hasDeletedPositions = Array.isArray(frm?.deletedPositions) && frm.deletedPositions.length > 0;

            if (!r || !r.message || !r.message.data) {
                console.error('Invalid response structure:', r);
                frappe.show_alert({
                    message: __('Некорректный формат ответа от сервера'),
                    indicator: 'red'
                }, 5);
                return;
            }

            if (!r.message.success) {
                frappe.show_alert({
                    message: responseMessage,
                    indicator: 'red'
                }, 5);
                return;
            }

            if (!Array.isArray(r.message.data.positions)) {
                return;
            }

            const filteredResult = filterPositionsAlreadyAdded(frm, r.message.data.positions);
            const responseData = {
                copied_count: filteredResult.positions.length,
                duplicates_count: (r.message.data.duplicates_count || 0) + filteredResult.duplicatesCount,
                invalid_count: r.message.data.invalid_count || 0,
                message: r.message.message || ''
            };

            if (filteredResult.positions.length === 0) {
                if (responseData.invalid_count > 0 || responseData.duplicates_count === 0 || hasDeletedPositions) {
                    handle_copy_positions_response(responseData);
                }
                return;
            }

            render_copied_positions(
                frm,
                filteredResult.positions,
                customers,
                fullDates,
                filteredHolidays
            );

            handle_copy_positions_response(responseData);
        },
        error: function(err) {
            handle_copy_positions_error(frm, err);
        }
    });
}


