// ISS-2025-02430: извлекает список ID задач из frm.tasks_data
function extractValidTaskIds(frm) {
    if (!frm.tasks_data || !Array.isArray(frm.tasks_data)) return [];

    let taskIds = [];
    for (const customer of frm.tasks_data) {
        for (const customerName in customer) {
            if (!customer.hasOwnProperty(customerName)) continue;
            const projects = customer[customerName];
            for (const project of projects) {
                const tasksIssues = project.tasks_issues;
                if (!tasksIssues || !Array.isArray(tasksIssues)) continue;
                for (const item of tasksIssues) {
                    if (item.tsdoctype === "Task" && item.name) {
                        taskIds.push(item.name);
                    }
                }
            }
        }
    }

    return taskIds;
}

// ISS-2025-02430: вызываем новый серверный метод для загрузки позиций из Project Workload Assignment
function handleCopyPlannedWorkloadPositions(frm, customers, fullDates, filteredHolidays) {
    const validTaskIds = extractValidTaskIds(frm);
    handleCopyRequest(
        frm,
        'copy_positions_from_project_workload_assignment',
        customers,
        fullDates,
        filteredHolidays,
        validTaskIds
    );
}

