                    }, 
                    limit: emails.length
                } );

                for ( var record of data ) {
                    let user = users.find((us) => us.name == record.comment_email);
                    record.full_name = user.full_name;
                }

                let d = new frappe.ui.Dialog({
                    title: __("История согласований"),
                    fields: [
                        {
                            label: __("Задача"),
                            fieldname: 'task',
